CREATE OR REPLACE FUNCTION public.content_erasure_sweep_sessions(lim integer, after_at timestamp with time zone, after_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
